const src = $json.body ?? $json;
const siteUrl = String(src.site_url ?? '').trim();
const businessSummary = String(src.business_summary ?? '').trim();
const audience = String(src.audience ?? '').trim();
const contentGoal = String(src.content_goal ?? '').trim();
const existingTopics = Array.isArray(src.existing_topics) ? src.existing_topics.map(String) : [];

if (!businessSummary) throw new Error('business_summary is required');
if (!audience) throw new Error('audience is required');

return [{
  json: {
    run_id: `content_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
    site_url: siteUrl,
    business_summary: businessSummary,
    audience,
    content_goal: contentGoal || 'Create useful content that supports business goals',
    existing_topics: existingTopics,
    state: 'RECEIVED',
    started_at: new Date().toISOString()
  }
}];

parameters.text:
=Create 4 focused web-research queries for content opportunity discovery.

Business: {{ $json.business_summary }}
Audience: {{ $json.audience }}
Content goal: {{ $json.content_goal }}
Existing topics to avoid: {{ JSON.stringify($json.existing_topics) }}

Queries should help discover recent problems, questions, market shifts, practical use cases, or credible evidence relevant to this audience. Do not write article titles yet.

parameters.jsonSchemaExample:
{
  "queries": [
    "AI automation operations challenges 2026",
    "workflow automation adoption small business 2026",
    "AI agent reliability business workflows",
    "operations leaders manual work automation examples"
  ]
}

parameters.jsCode:
const base = $('Normalize Content Brief').first().json;
const raw = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const queries = Array.isArray(raw.queries) ? raw.queries.filter(Boolean).slice(0,4) : [];
if (!queries.length) throw new Error('No research queries were generated');
return queries.map((query, index) => ({
  json: {
    ...base,
    state: 'RESEARCHING',
    query_index: index + 1,
    query: String(query)
  }
}));

const responses = $input.all();
const base = $('Normalize Content Brief').first().json;
const evidence = [];

for (const response of responses) {
  const results = Array.isArray(response.json.results) ? response.json.results : [];
  for (const r of results) {
    if (!r?.url) continue;
    evidence.push({
      title: String(r.title ?? ''),
      url: String(r.url),
      snippet: String(r.content ?? '').slice(0,1800),
      score: Number(r.score ?? 0)
    });
  }
}

const deduped = [];
const seen = new Set();
for (const e of evidence.sort((a,b) => b.score - a.score)) {
  if (seen.has(e.url)) continue;
  seen.add(e.url);
  deduped.push(e);
}

return [{
  json: {
    ...base,
    state: 'RESEARCH_COMPLETE',
    discovery_evidence: deduped.slice(0,16),
    evidence_count: deduped.length
  }
}];

parameters.text:
=Generate exactly five evidence-backed blog topic opportunities.

Business: {{ $json.business_summary }}
Audience: {{ $json.audience }}
Content goal: {{ $json.content_goal }}
Existing topics to avoid: {{ JSON.stringify($json.existing_topics) }}

Research evidence:
{{ JSON.stringify($json.discovery_evidence) }}

For each topic, include a specific angle, reader intent, why_now, supporting_urls chosen only from the evidence provided, confidence from 0 to 1, and an overlap_warning if it resembles an existing topic. Do not invent trends, statistics, or source URLs.

parameters.jsonSchemaExample:
{
  "topics": [
    {
      "title": "Why AI Automations Fail Quietly in Production",
      "angle": "Explain silent degradation and practical safeguards.",
      "target_reader": "Operations leaders evaluating AI automation",
      "intent": "Problem-aware / solution research",
      "why_now": "Recent evidence points to reliability becoming a deployment concern.",
      "supporting_urls": ["https://example.com/source"],
      "confidence": 0.86,
      "overlap_warning": "none"
    }
  ]
}

parameters.jsCode:
const base = $('Build Evidence Pack').first().json;
const raw = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const topics = Array.isArray(raw.topics) ? raw.topics.slice(0,5) : [];
if (topics.length !== 5) throw new Error('Expected exactly 5 topic opportunities');

return [{
  json: {
    ...base,
    state: 'WAITING_FOR_TOPIC_SELECTION',
    topics,
    topic_selection_url: $execution.resumeUrl,
    topic_selection_instruction: 'POST { topic_number: 1-5, reviewer: "name" } to the resume URL.'
  }
}];

const packet = $('Prepare Topic Selection').first().json;
const body = $json.body ?? $json;
const topicNumber = Number(body.topic_number ?? 0);
if (!Number.isInteger(topicNumber) || topicNumber < 1 || topicNumber > packet.topics.length) {
  throw new Error('topic_number must be an integer between 1 and 5');
}
const selected = packet.topics[topicNumber - 1];

return [{
  json: {
    ...packet,
    state: 'TOPIC_SELECTED',
    selected_topic_number: topicNumber,
    selected_topic: selected,
    topic_selected_by: String(body.reviewer ?? 'unknown'),
    topic_selected_at: new Date().toISOString()
  }
}];

const selection = $('Normalize Topic Selection').first().json;
const results = Array.isArray($json.results) ? $json.results : [];
const evidence = results.filter(r => r?.url).map(r => ({
  title: String(r.title ?? ''),
  url: String(r.url),
  snippet: String(r.content ?? '').slice(0,2200),
  score: Number(r.score ?? 0)
}));

return [{
  json: {
    ...selection,
    state: 'DEEP_RESEARCH_COMPLETE',
    deep_research_evidence: evidence
  }
}];

parameters.text:
=Write a useful evidence-aware blog article package.

Business context: {{ $json.business_summary }}
Audience: {{ $json.audience }}
Content goal: {{ $json.content_goal }}
Selected topic: {{ JSON.stringify($json.selected_topic) }}
Research evidence: {{ JSON.stringify($json.deep_research_evidence) }}

Requirements:
- write for the target reader, not for search engines
- do not fabricate statistics, quotes, studies, customer examples, or source claims
- retain source URLs from the supplied evidence
- if a claim is useful but not adequately supported, place it in claims_to_check instead of presenting it as fact
- avoid generic AI filler
- produce practical examples where possible without pretending they are real customer cases

