const draft = $('Normalize Draft').first().json;
const hero = $json.output && typeof $json.output === 'object' ? $json.output : $json;
return [{
  json: {
    ...draft,
    state: 'WAITING_FOR_EDITORIAL_REVIEW',
    hero_brief: hero,
    editorial_review_url: $execution.resumeUrl,
    editorial_instruction: 'POST decision=approve, revise, or reject with reviewer and optional feedback.'
  }
}];

const packet = $('Prepare Editorial Review').first().json;
const body = $json.body ?? $json;
let decision = String(body.decision ?? '').trim().toLowerCase();
if (!['approve','revise','reject'].includes(decision)) decision = 'reject';

return [{
  json: {
    ...packet,
    editorial_decision: decision,
    editorial_reviewer: String(body.reviewer ?? 'unknown'),
    editorial_feedback: String(body.feedback ?? ''),
    editorial_decided_at: new Date().toISOString()
  }
}];

parameters.text:
=Revise this article package using the editor's feedback.

Selected topic: {{ JSON.stringify($json.selected_topic) }}
Current article: {{ JSON.stringify($json.article) }}
Editor feedback: {{ $json.editorial_feedback }}
Research evidence: {{ JSON.stringify($json.deep_research_evidence) }}

Return a complete replacement article package. Preserve source discipline. Do not invent facts to satisfy the feedback.

parameters.jsCode:
const base = $('Normalize Editorial Decision').first().json;
const revised = $json.output && typeof $json.output === 'object' ? $json.output : $json;
return [{
  json: {
    ...base,
    state: 'WAITING_FOR_SECOND_REVIEW',
    revised_article: revised,
    second_review_url: $execution.resumeUrl
  }
}];

const packet = $('Prepare Second Review').first().json;
const body = $json.body ?? $json;
let decision = String(body.decision ?? '').trim().toLowerCase();
if (!['approve','reject'].includes(decision)) decision = 'reject';
return [{
  json: {
    ...packet,
    second_editorial_decision: decision,
    second_editorial_reviewer: String(body.reviewer ?? 'unknown'),
    second_editorial_feedback: String(body.feedback ?? ''),
    second_editorial_decided_at: new Date().toISOString()
  }
}];

const article = $json.revised_article ?? $json.article;
return [{
  json: {
    ...$json,
    state: 'READY_TO_PUBLISH',
    final_article: article,
    cms_payload: {
      title: article.title,
      slug: article.slug,
      excerpt: article.excerpt,
      body_markdown: article.body_markdown,
      meta_title: article.meta_title,
      meta_description: article.meta_description,
      hero_brief: $json.hero_brief,
      sources: article.sources ?? [],
      status: 'draft'
    }
  }
}];

return [{
  json: {
    run_id: $json.run_id,
    final_state: 'COMPLETE',
    selected_topic: $json.selected_topic?.title ?? null,
    article_title: ($json.final_article ?? $json.article)?.title ?? null,
    editorial_decision: $json.editorial_decision ?? null,
    second_editorial_decision: $json.second_editorial_decision ?? null,
    cms_payload_ready: Boolean($json.cms_payload),
    source_count: Array.isArray(($json.final_article ?? $json.article)?.sources) ? ($json.final_article ?? $json.article).sources.length : 0,
    completed_at: new Date().toISOString(),
    note: 'CMS publishing is disabled by default in the portfolio workflow.'
  }
}];

return [{
  json: {
    run_id: $json.run_id,
    final_state: 'REJECTED',
    selected_topic: $json.selected_topic?.title ?? null,
    editorial_decision: $json.editorial_decision ?? $json.second_editorial_decision ?? 'reject',
    rejection_feedback: $json.second_editorial_feedback ?? $json.editorial_feedback ?? '',
    published: false,
    completed_at: new Date().toISOString()
  }
}];
